  sheetRequest.current?.abort();setDetail({...f.properties,id:f.properties?.id??f.id});if(isPhone())pendingFocus.current=f;else engine.current?.focusFeature(f,cameraPadding());engine.current?.setSelected(f.properties?.personalSource?String(f.properties.id??f.id??''):'');setMobileExpanded(false);setLayersOpen(false);setSheetAsset(null);setSheetStatus('');
  if(f.properties?.personalSource||f.properties?.kind==='room'||f.properties?.kind==='access')return;setLayers(value=>({...value,galleries:true,sheets:true}));const controller=new AbortController();sheetRequest.current=controller;setSheetStatus('IGC planı aynı haritaya yükleniyor…');
  void getIgcSheet(f,controller.signal).then(async asset=>{if(controller.signal.aborted)return;setSheetAsset(asset);setSheetStatus('Plan bu haritada · cihazda kayıtlı');await refresh();if(!controller.signal.aborted)setStatus(`Pafta ${recordId(f)} aynı haritaya hizalandı ve çevrimdışı saklandı.`);}).catch(error=>{if(!controller.signal.aborted)setSheetStatus(error instanceof Error?error.message:String(error));});
