 async function openRoomModel(room:Room){const asset=await getRoomAsset(room.id);if(asset){setModelAsset({...asset,roomId:room.id});setDrawer(null);setMissingRoom(null);}else{setMissingRoom(room);setDrawer('archive');setStatus(`“${room.title}” modeli bu cihazda yok. Arşiv paketini bir kez ekleyebilirsin.`);}}
 function chooseDirectory(kind:typeof directoryKind){setDirectoryKind(kind);setQuery('');setOnlyFavorites(false);setAccessFilter('all');if(kind==='sheets')setLayers(value=>({...value,sheets:true}));if(kind==='rooms')setLayers(value=>({...value,rooms:true}));if(kind==='underground')setLayers(value=>({...value,underground:true}));if(kind==='access')setLayers(value=>({...value,access:true,underground:true}));setMobileExpanded(true);}
 function toggleLayer(id:keyof Visibility){setLayers(value=>({...value,[id]:!value[id]}));}
