    {landcoverState==='failed'&&ready&&<div className="landcover-notice" role="status">IGN arazi paketi alınamadı; Paris yüzey verisi gösteriliyor. <button className="text-button" onClick={()=>void loadLandcoverLayers()}>Arazi katmanını yeniden dene</button></div>}
