    {detail&&tab==='explore'&&<aside className={`detail-panel detail-${detailKind}${detailExpanded?' is-expanded':''}`} aria-label="Kayıt ayrıntısı"><div className="detail-header"><span className="eyebrow" data-testid="detail-eyebrow">{detailEyebrow}</span><button className="detail-expand text-button" aria-expanded={detailExpanded} onClick={()=>setDetailExpanded(v=>!v)}>{detailExpanded?'Haritayı göster':'Tümünü göster'}</button><button className="icon-button" aria-label="Ayrıntıyı kapat" onClick={()=>setDetail(null)}><Icon name="close" size={18}/></button></div>{detailKind==='room'?<RoomGallery key={`${selectedId}:${(roomPhotos[selectedId]?.length??0)>0}`} title={String(detail.title)} photos={roomPhotos[selectedId]??[]} poster={roomPosters[selectedId]??selectedRoom?.posterUrl} posterCredit={selectedRoom?.imageCredit}/>:detailKind==='private'&&(roomPhotos[selectedId]?.length??0)>0?<RoomGallery key={`private:${selectedId}`} title={String(detail.title)} photos={roomPhotos[selectedId]!} showScan={false}/>:detailKind==='sheet'&&sheetImage?<figure className="sheet-detail-preview"><img src={sheetImage} alt={`Pafta ${selectedId} · haritaya hizalı IGC planı`}/><figcaption>Bu alanın resmî IGC atlası</figcaption></figure>:detailKind==='sheet'?<div className="detail-sheet-illustration"><span className="sheet-illustration-grid"/><span className="detail-sheet-id">{selectedId}</span><span className="sheet-illustration-label">INSPECTION GÉNÉRALE<br/>DES CARRIÈRES</span><Icon name="plus" size={12}/></div>:<div className={`place-illustration ${detailKind==='access'?'is-access':''}`}><span className="place-illustration-rings"/>{detailKind==='private'&&detailStyle?<b className={`place-illustration-glyph access-${detailStyle}`} aria-hidden="true">{accessGlyphOf(detail)}</b>:<Icon name="pin" size={38}/>}<span>{detailDepth!==null?`−${detailDepth} m`:detailKind==='access'?'YERÜSTÜ':'DERİNLİK BELGELENMEMİŞ'}</span></div>}<div className="detail-content"><div className="detail-title-row"><h2>{detailKind==='sheet'?`Pafta ${selectedId}`:String(detail.title)}</h2><button className={`icon-button ${favorites.includes(selectedId)?'is-saved':''}`} onClick={()=>toggleFavorite(selectedId)} aria-label={favorites.includes(selectedId)?'Favorilerden çıkar':'Favorilere ekle'} aria-pressed={favorites.includes(selectedId)}><Icon name="star" size={21}/></button></div><p className="detail-subtitle">{detailKind==='sheet'?(detail.network==='GRS'?'Grand Réseau Sud çevresi':'Paris ve yakın çevresi'):detailKind==='private'?(detailGroup==='user'?'Kişisel işaret · kaynak konumu':'Kişisel yeraltı arşivi · kaynak çizimi'):detailKind==='room'?'Catacombes.xyz · yayıncı kaydı':'Les Catacombes de Paris · resmî kaynak'}</p><dl className="detail-facts">{detailKind==='sheet'?<><div><dt>Belge yılı</dt><dd>{String(detail.revisionYear??'Bilinmiyor')}</dd></div><div><dt>Kaynak</dt><dd>Ville de Paris · IGC</dd></div><div><dt>Gösterilen veri</dt><dd>{sheetAsset?'Koordinatlı galeri planı':'Pafta sınırı · plan yükleniyor'}</dd></div></>:<><div><dt>Derinlik</dt><dd>{detailDepth!==null?`Yüzeyden ${detailDepth} m`:detail.depthMetres===0||detailKind==='access'?'Yerüstü · sokak seviyesindeki adres':'Kaynakta belirtilmemiş'}</dd></div><div><dt>Konum</dt><dd data-testid="detail-position">{detailKind==='private'?<>{positionErrorLabel(detail.positionErrorM)?`${positionErrorLabel(detail.positionErrorM)} · `:'Yaklaşık · '}{Number.isFinite(detailRms)?`kaynaklar arası uyum RMS ${Math.round(detailRms)} m (ölçüm doğruluğu değil)`:'tarihî plan hizası'}</>:selectedFeature?'Kaynak koordinatı':'Konum kaydı yok'}</dd></div><div><dt>Kayıt türü</dt><dd>{detailKind==='private'?String(detail.sourceCategoryLabel??(detailGroup?accessLabel[detailGroup]:'Tarihî galeri çizgisi')):detailKind==='room'?'Yeraltı salonu':'Resmî müze erişimi'}</dd></div>{detailKind==='private'&&detailGroup&&<div><dt>Güncel erişim</dt><dd>Bilinmiyor · açık giriş anlamına gelmez</dd></div>}{detailKind==='private'&&<>{typeof detail.sourceLabel==='string'&&<div><dt>Kaynak katmanı</dt><dd>{detail.sourceLabel}</dd></div>}{typeof detail.sourceAlignmentNote==='string'&&<div><dt>Hizalama dayanağı</dt><dd>{detail.sourceAlignmentNote.slice(0,500)}</dd></div>}{typeof detail.waterLabel==='string'&&<div><dt>Kaynakta su işareti</dt><dd>{detail.waterLabel} · güncel durum değişebilir</dd></div>}{sourceProximityLabel(detail.sourceProximity)&&<div><dt>Kaynaklar arası yakınlık</dt><dd data-testid="source-proximity">{sourceProximityLabel(detail.sourceProximity)}</dd></div>}{detailGroup==='user'&&typeof detail.cameraHeadingDeg==='number'&&<div><dt>Kaynak görüntüsü bakışı</dt><dd>{Math.round(detail.cameraHeadingDeg)}° · tünel yönü değildir</dd></div>}<div className="detail-source-id"><dt>Kaynak kimliği</dt><dd data-testid="detail-source-id">{String(detail.id??'')}</dd></div></>}{typeof detail.checkedAt==='string'&&<div><dt>Kaynak kontrolü</dt><dd>{date(detail.checkedAt)}</dd></div>}</>}</dl><p className="detail-description">{detailKind==='sheet'?'Eski taş ocakları atlasının bu bölgesine ait belge. Haritadaki alan, belgenin kapsadığı sınırdır.':detailKind==='private'?(detailGroup==='user'?'Kişisel olarak işaretlenen kaynak konumu. Girişin açık olduğu veya buradan erişilebildiği doğrulanmış değildir.':`Kaynak yılı: ${String(detail.sourceMapYear??detail.sourceYear??'belirtilmemiş')}. Tarihî çizimden yaklaşık harita konumu; saha ölçümü değildir.`):detail.description?String(detail.description):'Salonun kaynağında yayımlanan konum ve derinlik kaydı. Model arşivini eklediğinde mekânı uygulamanın içinde inceleyebilirsin.'}</p>{detailKind==='sheet'?<><button className="button button-dark detail-source" onClick={()=>selectedFeature&&selectFeature(selectedFeature)}><Icon name="layers" size={17}/>Paftayı aynı haritada göster</button><p className="link-caption" role="status" data-testid="sheet-overlay-status">{sheetStatus}</p>{sheetAsset&&<button className="button button-plain" onClick={()=>{setDetail(null);setMapWide(true);}}>Planı geniş haritada incele</button>}<ExternalLink url={detail.pdfUrl} className="text-button detail-citation">Arşiv PDF belgesi · ek kaynak</ExternalLink></>:detailKind==='room'?<><button className="button button-dark detail-source" onClick={()=>void run(()=>openRoomModel(selectedRoom??{id:selectedId,title:String(detail.title),url:String(detail.sourceUrl??''),sourceId:'catacombes-xyz',localModelAvailable:false,coordinates:centerOf(selectedFeature),depthMetres:typeof detail.depthMetres==='number'?detail.depthMetres:null}))}><Icon name="cube" size={17}/>Modeli uygulamada aç<Icon name="arrow" size={16}/></button><p className="link-caption">{roomAvailable(selectedId)?'Bu cihazda · çevrimdışı':'Bir kez kişisel arşiv paketi ekle'}</p><button className="button button-plain detail-note" onClick={()=>setSpatialOpen(true)}><Icon name="layers" size={16}/>3B derinlik ve kesit</button></>:detailKind==='private'?<p className="scope-note">{detailGroup==='user'?'Kişisel işaret · girişin açık veya erişilebilir olduğu doğrulanmadı. Kamera konumu gerçek yeraltı giriş konumuyla aynı olmayabilir.':'Tarihî kaynak kaydı · güncel erişim durumu bilinmiyor. Konumlar ölçülü saha doğrulaması değildir; şaft kaydı açık giriş anlamına gelmez.'}</p>:<ExternalLink url={detail.sourceUrl} className="button button-dark detail-source">Resmî ziyaret bilgisini aç</ExternalLink>}<button className="button button-plain detail-note" onClick={openNotebook}><Icon name="plus" size={17}/>Bu noktaya not ekle</button>{detailKind!=='sheet'&&<ExternalLink url={detail.sourceUrl} className="text-button detail-citation">Kaynak kaydını incele</ExternalLink>}<div className="detail-context"><Icon name="info" size={15}/><p>{detailKind==='sheet'?'Resmî IGC mosaiki bu paftanın coğrafi alanına hizalanır. Arşiv PDF baskısıyla mosaik farklı revizyonlar içerebilir; belge yılı açık geçiş bilgisi değildir.':detailKind==='private'?(detailGroup==='user'?'Kişisel işaret saha doğrulaması değildir. Kaynak görüntüsünün bakışı tünel yönü veya erişim garantisi vermez.':'Tarihî plandan aktarılmış kişisel veri. Çizgiler ölçülü 3B duvar veya güncel geçiş bilgisi değildir.'):detailKind==='room'?'Yayıncı koordinatı erişim garantisi değildir. Ayrı salon modelleri, ölçülü birleşik bir yeraltı ağı oluşturmaz.':'Bu kayıt resmî müzenin giriş veya çıkışıdır. Ziyaret koşullarını resmî kaynağından kontrol et.'}</p></div></div></aside>}
